using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private static readonly List<Department> Departments =
    [
        new() { Id = 1, Name = "Computer Science", Abbreviation = "CS" },
        new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH" },
        new() { Id = 3, Name = "English", Abbreviation = "ENG" },
        new() { Id = 4, Name = "Physics", Abbreviation = "PHYS" },
        new() { Id = 5, Name = "History", Abbreviation = "HIST" },
    ];

    private static readonly List<Course> Courses =
    [
        new()
        {
            Id = 1, CourseCode = "CS 101", Title = "Introduction to Programming",
            Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, functions, and object-oriented design principles.",
            Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, DepartmentName = "Computer Science",
            InstructorName = "Dr. Ada Lovelace", InstructorBio = "Dr. Lovelace has 15 years of experience teaching introductory programming and has authored two textbooks on software fundamentals.",
            IsFeatured = true
        },
        new()
        {
            Id = 2, CourseCode = "CS 201", Title = "Data Structures and Algorithms",
            Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques including sorting, searching, and dynamic programming.",
            Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", DepartmentId = 1, DepartmentName = "Computer Science",
            InstructorName = "Dr. Alan Turing", InstructorBio = "Dr. Turing specializes in algorithm complexity theory and has published extensively on efficient data processing.",
            IsFeatured = false
        },
        new()
        {
            Id = 3, CourseCode = "CS 310", Title = "Web Application Development",
            Description = "Build modern web applications using ASP.NET Core, Blazor, and cloud services. Covers front-end design, server-side logic, and database integration.",
            Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", DepartmentId = 1, DepartmentName = "Computer Science",
            InstructorName = "Dr. Tim Berners-Lee", InstructorBio = "Dr. Berners-Lee brings industry experience from major tech companies and focuses on practical, project-based learning.",
            IsFeatured = true
        },
        new()
        {
            Id = 4, CourseCode = "MATH 101", Title = "Calculus I",
            Description = "Introduction to differential calculus including limits, derivatives, and applications to real-world problems in science and engineering.",
            Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = 2, DepartmentName = "Mathematics",
            InstructorName = "Dr. Emmy Noether", InstructorBio = "Dr. Noether is an award-winning educator known for making abstract mathematics accessible to all students.",
            IsFeatured = true
        },
        new()
        {
            Id = 5, CourseCode = "MATH 201", Title = "Linear Algebra",
            Description = "Vectors, matrices, linear transformations, eigenvalues, and applications to computer graphics and data science.",
            Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", DepartmentId = 2, DepartmentName = "Mathematics",
            InstructorName = "Dr. Carl Gauss", InstructorBio = "Dr. Gauss has contributed to research in numerical methods and teaches with an emphasis on geometric intuition.",
            IsFeatured = false
        },
        new()
        {
            Id = 6, CourseCode = "ENG 101", Title = "College Composition",
            Description = "Develop clear, effective writing skills through essay composition, peer review, and revision. Emphasis on argumentation and critical thinking.",
            Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = 3, DepartmentName = "English",
            InstructorName = "Dr. Maya Angelou", InstructorBio = "Dr. Angelou is a published author and poet who brings creative energy to academic writing instruction.",
            IsFeatured = false
        },
        new()
        {
            Id = 7, CourseCode = "ENG 220", Title = "American Literature",
            Description = "Survey of American literature from the colonial period to the present, exploring themes of identity, democracy, and social change.",
            Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", DepartmentId = 3, DepartmentName = "English",
            InstructorName = "Dr. Mark Twain", InstructorBio = "Dr. Twain specializes in 19th-century American fiction and brings humor and storytelling to literary analysis.",
            IsFeatured = false
        },
        new()
        {
            Id = 8, CourseCode = "PHYS 101", Title = "General Physics I",
            Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions with hands-on experiments.",
            Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 2:00–4:50 PM", DepartmentId = 4, DepartmentName = "Physics",
            InstructorName = "Dr. Marie Curie", InstructorBio = "Dr. Curie combines rigorous theory with engaging laboratory demonstrations to make physics intuitive.",
            IsFeatured = true
        },
        new()
        {
            Id = 9, CourseCode = "PHYS 250", Title = "Modern Physics",
            Description = "Introduction to relativity, quantum mechanics, and atomic physics. Explores the physics of the 20th century and beyond.",
            Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM", DepartmentId = 4, DepartmentName = "Physics",
            InstructorName = "Dr. Richard Feynman", InstructorBio = "Dr. Feynman is celebrated for his clear explanations of complex topics and his interactive lecture style.",
            IsFeatured = false
        },
        new()
        {
            Id = 10, CourseCode = "HIST 101", Title = "World History to 1500",
            Description = "Survey of world civilizations from prehistory through the Renaissance, examining political, social, and cultural developments.",
            Credits = 3, Schedule = "Mon/Wed 10:00–11:15 AM", DepartmentId = 5, DepartmentName = "History",
            InstructorName = "Dr. Howard Zinn", InstructorBio = "Dr. Zinn takes a people-centered approach to history, encouraging students to consider multiple perspectives on historical events.",
            IsFeatured = false
        },
        new()
        {
            Id = 11, CourseCode = "HIST 205", Title = "The American Civil War",
            Description = "In-depth study of the causes, major battles, political leaders, and lasting consequences of the American Civil War.",
            Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", DepartmentId = 5, DepartmentName = "History",
            InstructorName = "Dr. Shelby Foote", InstructorBio = "Dr. Foote is a narrative historian who uses primary sources and storytelling to bring the Civil War era to life.",
            IsFeatured = false
        },
    ];

    public List<Department> GetDepartments() => Departments;

    public Department? GetDepartment(int id) => Departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = Courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public List<Course> GetFeaturedCourses() => Courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => Courses.FirstOrDefault(c => c.Id == id);
}

